'use client';

// PROTOTYPE, throwaway: the real sidebar, optionally fed with example sessions so every state can be
// looked at. Only in builds made with NEXT_PUBLIC_PROTOTYPE=1 (or the dev server); delete before
// this reaches main.

import './preview.css';
import { useEffect, useMemo, useState, type ComponentProps } from 'react';
import type { Route } from '@/lib/route';
import type { Session } from '@/lib/types';
import { Sidebar } from '../Sidebar';
import { MOCK_SESSIONS } from './mock';

const SHOW = process.env.NODE_ENV !== 'production' || process.env.NEXT_PUBLIC_PROTOTYPE === '1';

export function PreviewSidebar(props: ComponentProps<typeof Sidebar>) {
  const [mock, setMock] = useState(false);
  const [mockRoute, setMockRoute] = useState<Route | null>(null);
  const [list, setList] = useState<Session[]>(MOCK_SESSIONS as Session[]);

  useEffect(() => {
    try {
      setMock(sessionStorage.getItem('proto.mock') !== '0');
    } catch {}
  }, []);

  const data = useMemo(() => {
    if (!mock) return props;
    const route = mockRoute ?? { view: 'session' as const, session: MOCK_SESSIONS[1]!.id };
    // The menu works on the examples too, in memory only.
    const edit = (id: string, c: Partial<Session>) => {
      setList((l) => l.map((s) => (s.id === id ? { ...s, ...c } : s)));
      return Promise.resolve();
    };
    return {
      ...props,
      route,
      go: (r: Route) => (r.session?.startsWith('mock_') ? setMockRoute(r) : props.go(r)),
      sessions: list,
      loaded: true,
      actions: {
        rename: (id: string, title: string) => edit(id, { title }),
        pin: (id: string, pinned: boolean) => edit(id, { pinned }),
        archive: (id: string, archived: boolean) => edit(id, { archived: archived ? new Date().toISOString() : undefined }),
        remove: (id: string) => {
          setList((l) => l.filter((s) => s.id !== id));
          return Promise.resolve();
        },
      },
    };
  }, [mock, mockRoute, props, list]);

  if (!SHOW) return <Sidebar {...props} />;
  return (
    <>
      <Sidebar {...data} />
      <div className="proto-bar" role="toolbar" aria-label="Sidebar preview">
        <label className="proto-mock">
          <input
            type="checkbox"
            checked={mock}
            onChange={(e) => {
              setMock(e.target.checked);
              try {
                sessionStorage.setItem('proto.mock', e.target.checked ? '1' : '0');
              } catch {}
            }}
          />
          dados de exemplo
        </label>
      </div>
    </>
  );
}
