// PROTOTYPE example data: every state a session can be in, so each variant shows all of them.

const min = (m: number) => new Date(Date.now() - m * 60_000).toISOString();

function session(id: string, state: string, cwd: string, prompt: string, ago: number, extra: object = {}) {
  return {
    id: `mock_${id}`,
    agent: 'claude',
    cwd,
    created: min(ago + 30),
    last_seq: 40,
    state,
    pending: state === 'waiting' ? 1 : 0,
    updated: min(ago),
    last_run: {
      id: `run_${id}`,
      session: `mock_${id}`,
      prompt,
      status: state === 'working' || state === 'waiting' ? 'running' : 'done',
      started: min(ago + 4),
    },
    ...extra,
  };
}

